'use client'

import { useRouter, usePathname } from 'next/navigation'
import { useEffect, useState, type ReactNode } from 'react'

type NavItem = { label: string; href: string; ready: boolean }

// The 9 sections from the spec. Only the ones built so far route anywhere;
// the rest are shown greyed with a "soon" tag so the full shape is visible.
const NAV: NavItem[] = [
  { label: 'Dashboard', href: '/moderator', ready: true },
  { label: 'Farmer onboarding', href: '/moderator/farmers', ready: true },
  { label: 'Escalations', href: '/moderator/escalations', ready: true },
  { label: 'Listings', href: '/moderator/listings', ready: true },
  { label: 'Consumers', href: '/moderator/consumers', ready: true },
  { label: 'Delivery agents', href: '/moderator/agents', ready: true },
  { label: 'Price management', href: '/moderator/prices', ready: true },
  { label: 'Supply & demand', href: '/moderator/supply', ready: true },
  { label: 'Reports', href: '/moderator/reports', ready: true },
]

export default function ModeratorShell({
  title,
  subtitle,
  zone,
  children,
}: {
  title: string
  subtitle?: string
  zone: string
  children: ReactNode
}) {
  const router = useRouter()
  const pathname = usePathname()
  const [menuOpen, setMenuOpen] = useState(false)

  const logout = async () => {
    await fetch('/api/moderator/logout', { method: 'POST', credentials: 'same-origin' }).catch(() => null)
    router.replace('/moderator/login')
  }

  const zoneLabel = zone.charAt(0).toUpperCase() + zone.slice(1)

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <aside
        className={`fixed md:static z-30 inset-y-0 left-0 w-60 bg-green-950 text-green-50 flex-col transition-transform ${
          menuOpen ? 'flex translate-x-0' : 'hidden md:flex md:translate-x-0'
        }`}
      >
        <div className="px-5 pt-6 pb-5 border-b border-green-900/60">
          <p className="text-lg font-extrabold tracking-tight text-white">GoGrameen</p>
          <p className="text-[11px] text-green-300/80">Moderator · {zoneLabel}</p>
        </div>
        <nav className="flex-1 py-3">
          {NAV.map((item) => {
            const active = pathname === item.href
            if (!item.ready) {
              return (
                <div
                  key={item.href}
                  className="flex items-center justify-between px-5 py-2.5 text-sm text-green-300/40 cursor-not-allowed"
                >
                  <span>{item.label}</span>
                  <span className="text-[9px] uppercase bg-green-900/50 px-1.5 py-0.5 rounded">soon</span>
                </div>
              )
            }
            return (
              <button
                key={item.href}
                onClick={() => { setMenuOpen(false); router.push(item.href) }}
                className={`w-full text-left px-5 py-2.5 text-sm transition-colors ${
                  active ? 'bg-green-800 text-white font-semibold border-l-4 border-green-300' : 'text-green-100 hover:bg-green-900/60'
                }`}
              >
                {item.label}
              </button>
            )
          })}
        </nav>
        <button onClick={logout} className="px-5 py-4 text-xs text-green-300 hover:text-white text-left border-t border-green-900/60">
          Log out
        </button>
      </aside>

      {menuOpen && (
        <div className="fixed inset-0 bg-black/40 z-20 md:hidden" onClick={() => setMenuOpen(false)} />
      )}

      {/* Main */}
      <div className="flex-1 min-w-0">
        <header className="bg-white border-b border-gray-100 px-4 md:px-8 py-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-3 min-w-0">
            <button onClick={() => setMenuOpen(true)} className="md:hidden text-gray-700 text-xl leading-none">☰</button>
            <div className="min-w-0">
              <h1 className="text-lg md:text-xl font-extrabold text-gray-900 leading-tight truncate">{title}</h1>
              {subtitle && <p className="text-xs text-gray-500 truncate">{subtitle}</p>}
            </div>
          </div>
          <span className="text-[11px] font-semibold bg-green-100 text-green-800 px-3 py-1 rounded-full whitespace-nowrap">
            {zoneLabel} zone
          </span>
        </header>
        <main className="p-4 md:p-8 max-w-5xl">{children}</main>
      </div>
    </div>
  )
}

// Shared client-side auth guard. Returns the zone once confirmed, or redirects
// to /moderator/login. Every moderator page uses this so a farmer / consumer /
// rider who lands on a /moderator URL is bounced out immediately.
export function useModeratorAuth() {
  const router = useRouter()
  const [zone, setZone] = useState<string | null>(null)
  const [checked, setChecked] = useState(false)

  useEffect(() => {
    let cancelled = false
    fetch('/api/moderator/me', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return
        if (json?.moderator) { setZone(json.zone); setChecked(true) }
        else router.replace('/moderator/login')
      })
      .catch(() => { if (!cancelled) router.replace('/moderator/login') })
    return () => { cancelled = true }
  }, [router])

  return { zone, checked }
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Farmer = {
  id: string
  slug: string
  name: string
  village: string | null
  district: string | null
  method: string | null
  phone: string | null
  active: boolean
  listing_count: number
}

const METHOD_LABEL: Record<string, string> = {
  natural: 'Natural',
  low_chemical: 'Low chem',
  chemical: 'Chemical',
}

export default function ModeratorFarmersPage() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [farmers, setFarmers] = useState<Farmer[]>([])
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const load = useCallback(async () => {
    const r = await fetch('/api/moderator/farmers', { credentials: 'same-origin' }).catch(() => null)
    setLoading(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load farmers.'); return }
    setFarmers((json.farmers ?? []) as Farmer[])
  }, [])

  useEffect(() => { if (checked) void load() }, [checked, load])

  const toggleActive = async (f: Farmer) => {
    if (busyId) return
    setBusyId(f.id)
    const r = await fetch(`/api/moderator/farmers/${f.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ active: !f.active }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) { setError('Update failed.'); return }
    setFarmers((list) => list.map((x) => (x.id === f.id ? { ...x, active: !x.active } : x)))
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const activeCount = farmers.filter((f) => f.active).length

  return (
    <ModeratorShell title="Farmer onboarding" subtitle="Register a new farmer or manage existing ones" zone={zone}>
      <div className="flex items-center justify-between mb-4">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide">
          {activeCount} active farmer{activeCount !== 1 ? 's' : ''} in zone
        </p>
        <button
          onClick={() => router.push('/moderator/farmers/new')}
          className="bg-green-800 text-white text-sm font-bold px-4 py-2 rounded-xl active:bg-green-900"
        >
          + Add new farmer
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-2 text-sm font-semibold mb-4">{error}</div>
      )}

      {loading ? (
        <p className="text-sm text-gray-400 py-10 text-center">Loading…</p>
      ) : farmers.length === 0 ? (
        <div className="text-center py-14 bg-white rounded-2xl border border-gray-100">
          <div className="text-5xl mb-3">🌾</div>
          <p className="font-semibold text-gray-500 text-sm">No farmers yet in this zone</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
          {/* header row — hidden on mobile */}
          <div className="hidden md:grid grid-cols-12 gap-2 px-4 py-2.5 text-[10px] font-bold text-gray-400 uppercase border-b border-gray-100">
            <div className="col-span-4">Farmer</div>
            <div className="col-span-3">Village</div>
            <div className="col-span-2">Method</div>
            <div className="col-span-1 text-center">Listings</div>
            <div className="col-span-2 text-right">Status</div>
          </div>
          {farmers.map((f) => (
            <div key={f.id} className="grid grid-cols-12 gap-2 items-center px-4 py-3 border-b border-gray-50 last:border-0">
              <div className="col-span-12 md:col-span-4 min-w-0">
                <p className="font-bold text-gray-900 text-sm truncate">{f.name}</p>
                <a href={`/farmer/${f.slug}`} target="_blank" className="text-[11px] text-green-700 underline">/farmer/{f.slug}</a>
              </div>
              <div className="col-span-6 md:col-span-3 text-sm text-gray-600 truncate">{f.village || '—'}</div>
              <div className="col-span-6 md:col-span-2">
                <span className="text-[11px] font-semibold bg-green-100 text-green-800 px-2 py-0.5 rounded-full">
                  {METHOD_LABEL[f.method ?? ''] ?? f.method ?? '—'}
                </span>
              </div>
              <div className="col-span-4 md:col-span-1 text-sm text-gray-700 md:text-center">{f.listing_count}</div>
              <div className="col-span-8 md:col-span-2 flex items-center justify-end gap-2">
                <span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full ${f.active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-500'}`}>
                  {f.active ? 'Active' : 'Inactive'}
                </span>
                <button
                  onClick={() => toggleActive(f)}
                  disabled={busyId === f.id}
                  className="text-[11px] text-gray-500 underline disabled:opacity-50"
                >
                  {f.active ? 'Deactivate' : 'Activate'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </ModeratorShell>
  )
}

